package com.nexus.domain; import jakarta.persistence.*; import com.nexus.domain.Rules.*;
@Entity @Table(name="sla_policies") public class SlaPolicy{@Id public String id; public Long serviceId; @Enumerated(EnumType.STRING) public Priority priority; public int responseMinutes,resolutionMinutes,warningMinutes; protected SlaPolicy(){} public SlaPolicy(Long service,Priority p,Target t){id=key(service,p);serviceId=service;priority=p;responseMinutes=t.responseMinutes();resolutionMinutes=t.resolutionMinutes();warningMinutes=t.warningMinutes();} public Target target(){return new Target(responseMinutes,resolutionMinutes,warningMinutes);} public static String key(Long service,Priority p){return (service==null?"default":service.toString())+":"+p;}}
